import {padButton} from './gamepads.js';
/** Independent player actions. DOM binding is optional and has one cleanup owner. */
export class ActionInput{
 constructor(players=1,{gamepad={}}={}){this.gamepad={jump:0,interact:2,attack:1,cast:3,dodge:4,run:5,...gamepad};this.players=Array.from({length:players},()=>({x:0,z:0,run:false,jump:false,interact:false,attack:false,cast:false,dodge:false}));this.keys=new Set();this.touch=new Map();this.selected=0;}
 pulse(player,action){if(this.players[player])this.players[player][action]=true;}
 stick(player,x,z){this.touch.set(player,{x,z});}
 release(player){this.touch.delete(player);}
 read(player,gamepad=null){const p=this.players[player],keys=this.keys,map=player===0?['KeyA','KeyD','KeyW','KeyS','Space','KeyE']:['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Numpad0','Enter'];let x=+keys.has(map[1])-+keys.has(map[0]),z=+keys.has(map[3])-+keys.has(map[2]);const t=this.touch.get(player);if(t){x=t.x;z=t.z;}if(gamepad){const a=gamepad.axes||[];if(Math.hypot(a[0]||0,a[1]||0)>.18){x=a[0];z=a[1];}for(const action of ['jump','interact','attack','cast','dodge']){const down=padButton(gamepad,this.gamepad[action]);if(down&&!p['pad'+action])p[action]=true;p['pad'+action]=down;}}
  const result={x,z,run:p.run||keys.has(player?'Numpad1':'ShiftLeft')||padButton(gamepad,this.gamepad.run),jump:p.jump,interact:p.interact,attack:p.attack,cast:p.cast,dodge:p.dodge};p.jump=p.interact=p.attack=p.cast=p.dodge=false;return result;}
 key(code,down){const extra={KeyF:[0,'attack'],KeyR:[0,'cast'],KeyC:[0,'dodge'],Numpad2:[1,'attack'],Numpad3:[1,'cast'],Numpad4:[1,'dodge']};const map=extra[code]|| (code==='Space'? [0,'jump']:code==='KeyE'?[0,'interact']:code==='Numpad0'?[1,'jump']:code==='Enter'?[1,'interact']:null);if(down&&!this.keys.has(code)&&map)this.pulse(...map);if(down)this.keys.add(code);else this.keys.delete(code);}
 clear(){this.keys.clear();this.touch.clear();for(const p of this.players){p.jump=p.interact=p.attack=p.cast=p.dodge=p.run=p.padJump=p.padUse=p.padjump=p.padinteract=p.padattack=p.padcast=p.paddodge=false;}}
}
export function bindActionInput(root,input,{target=window,onPause=()=>{},onSelect=()=>{},enabled=()=>true,pauseEnabled=enabled}={}){
 const clean=[],listen=(el,n,fn,options)=>{el.addEventListener(n,fn,options);clean.push(()=>el.removeEventListener(n,fn,options));};
 const keyboard=e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target?.tagName||''))return;if(e.code==='Escape'&&e.type==='keydown'&&!e.repeat&&pauseEnabled()){onPause();return;}if(!enabled())return;if(e.code==='Tab'&&e.type==='keydown'&&!e.repeat){e.preventDefault();input.selected=(input.selected+1)%input.players.length;onSelect(input.selected);return;}if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Enter','Numpad0','Numpad1','Numpad2','Numpad3','Numpad4','KeyE','KeyF','KeyR','KeyC'].includes(e.code))e.preventDefault();input.key(e.code,e.type==='keydown');};listen(target,'keydown',keyboard);listen(target,'keyup',keyboard);listen(target,'blur',()=>input.clear());
 for(const stick of root.querySelectorAll('[data-stick]')){let pointer=null;const owner=+stick.dataset.stick,move=e=>{if(e.pointerId!==pointer)return;e.preventDefault();const r=stick.getBoundingClientRect(),x=Math.max(-1,Math.min(1,(e.clientX-r.left-r.width/2)/(r.width*.34))),z=Math.max(-1,Math.min(1,(e.clientY-r.top-r.height/2)/(r.height*.34)));input.stick(owner,x,z);stick.style.setProperty('--jx',x*24+'px');stick.style.setProperty('--jy',z*24+'px');};listen(stick,'pointerdown',e=>{if(!enabled()||pointer!==null)return;pointer=e.pointerId;stick.setPointerCapture(pointer);move(e);});listen(stick,'pointermove',move);const release=e=>{if(e.pointerId!==pointer)return;pointer=null;input.release(owner);stick.style.setProperty('--jx','0px');stick.style.setProperty('--jy','0px');};for(const name of ['pointerup','pointercancel','lostpointercapture'])listen(stick,name,release);}
 for(const b of root.querySelectorAll('[data-action]'))listen(b,'pointerdown',e=>{if(!enabled())return;e.preventDefault();input.pulse(+b.dataset.player,b.dataset.action);});
 for(const b of root.querySelectorAll('[data-run]')){const player=+b.dataset.run;listen(b,'click',()=>{if(!enabled())return;input.players[player].run=!input.players[player].run;b.setAttribute('aria-pressed',String(input.players[player].run));});}
 return{dispose(){input.clear();clean.forEach(f=>f());}};
}
